import json
import sys
from datetime import datetime, timezone, timedelta


def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 datetime string."""
    if s is None:
        return None
    # Handle 'Z' suffix
    s = s.replace("Z", "+00:00")
    # Python 3.7+ fromisoformat handles offsets like +00:00
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        return None  # naive datetime — skip
    return dt


def format_utc(dt):
    """Format a datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    utc_dt = dt.astimezone(timezone.utc)
    return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def main():
    with open(sys.argv[1], "r") as f:
        data = json.load(f)

    as_of_dt = parse_offset_aware(data["as_of"])
    if as_of_dt is None:
        print("[]")
        return

    results = []
    for r in data.get("reminders", []):
        # Skip completed reminders
        if r.get("completed", False):
            continue

        due_str = r.get("due")
        # Skip missing, null, or naive due values
        if due_str is None:
            continue
        due_dt = parse_offset_aware(due_str)
        if due_dt is None:
            continue

        # Include only reminders due AT OR BEFORE as_of
        if due_dt <= as_of_dt:
            results.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": format_utc(due_dt),
                "_due_dt": due_dt,  # for sorting, removed later
            })

    # Sort by actual due instant, then by id
    results.sort(key=lambda x: (x["_due_dt"], x["id"]))

    # Remove internal sorting key
    for item in results:
        del item["_due_dt"]

    print(json.dumps(results))


if __name__ == "__main__":
    main()
